// Pull onboarding inputs from whichever trigger fired.
// Webhook puts params under $json.query; Execute Workflow Trigger and Manual put them at top level.
const src = $input.first().json || {};
const q = src.query || {};
const pick = (k) => (src[k] !== undefined && src[k] !== '' ? src[k] : (q[k] !== undefined && q[k] !== '' ? q[k] : ''));

const clientName = String(pick('clientName') || 'Valued Client').trim();
const projectName = String(pick('projectName') || 'Your Project').trim();
const startDate = String(pick('startDate') || '').trim();

return [{ json: { clientName, projectName, startDate } }];

// Vera (client concierge) writes a warm onboarding packet.
const { clientName, projectName, startDate } = $json;

const system = `You are Vera, the client concierge for a solo software agency based in Berlin. You write all client-facing communication. Voice: warm, calm, professional, concrete. Plain language — never jargon, never hype. At most one exclamation mark per message. Every message ends with exactly one clear next step or question. Mirror the client's language (German or English) and formality; in German default to "Sie" unless the client used "du". Never invent prices, deadlines, scope, or commitments — if a fact is missing, insert a literal [PLACEHOLDER: what's needed] and flag it. Never apologize more than once. Sign off as the agency owner, not as an AI. Output only the message body unless asked otherwise.`;

const task = `Write a warm client onboarding packet for the client below. Respond in ENGLISH.

Client: ${clientName}
Project: ${projectName}
Start / kickoff date: ${startDate || '[PLACEHOLDER: kickoff date not provided]'}

Return ONLY a single valid JSON object (no markdown, no code fences, no prose before or after) with EXACTLY these keys:
{
  "welcome": "2-3 warm sentences welcoming ${clientName} to the project. Address the client by name.",
  "steps": ["4 short timeline items describing what happens next, in order (e.g. kickoff call, discovery, first milestone, review). Each item is one short sentence."],
  "checklist": ["4 short items describing what we need FROM the client to start (assets, access, decisions). Each one short line."],
  "comms_policy": "2 sentences on how we communicate (channels, response times, weekly update cadence). Use [PLACEHOLDER: ...] for any specific detail you do not have.",
  "tools": "a short comma-separated list of tools we'll use together (e.g. email, shared drive, project board)"
}
Do not invent dates or prices. If the kickoff date is missing, do not guess one. Keep every string concise and client-ready.`;

return [{ json: { model: 'qwen3:8b', prompt: system + '

' + task, clientName, projectName, startDate } }];

// Fill templates/onboarding.html (inlined) with the model's JSON output.
const TEMPLATE = "<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"utf-8\">\n<style>\n  :root{\n    --brand:#1F3A5F; --accent:#3E7CB1; --ink:#1A1A1A; --muted:#6B7280;\n    --line:#E5E7EB; --bg-soft:#F7F9FC; --font:'Helvetica Neue',Arial,sans-serif;\n  }\n  @page{ size:A4; margin:18mm 16mm; }\n  *{ box-sizing:border-box; -webkit-print-color-adjust:exact; print-color-adjust:exact; }\n  body{ font-family:var(--font); color:var(--ink); font-size:11pt; line-height:1.5; margin:0; }\n  h1{ color:var(--brand); font-size:22pt; margin:0 0 4px; }\n  h2{ color:var(--brand); font-size:13pt; border-bottom:2px solid var(--accent);\n      padding-bottom:4px; margin:24px 0 10px; }\n  .muted{ color:var(--muted); } .small{ font-size:9pt; }\n  .brandbar{ height:6px; background:linear-gradient(90deg,var(--brand),var(--accent)); }\n  table{ width:100%; border-collapse:collapse; margin:8px 0; }\n  td{ padding:8px 10px; border-bottom:1px solid var(--line); vertical-align:top; }\n  tr:nth-child(even) td{ background:var(--bg-soft); }\n  .logo{ height:40px; }\n</style>\n</head>\n<body>\n<div class=\"brandbar\"></div>\n<div style=\"margin-top:50px\">\n  <img class=\"logo\" src=\"data:image/png;base64,{{LOGO_B64}}\" alt=\"{{AGENCY_NAME}}\">\n  <h1>Welcome aboard, {{CLIENT_FIRST_NAME}}</h1>\n  <p class=\"muted\">Your onboarding guide with {{AGENCY_NAME}}</p>\n</div>\n<h2>What happens next</h2>\n{{STEPS_LIST}}\n<h2>Your project at a glance</h2>\n<table>\n  <tbody>\n    <tr><td><strong>Project</strong></td><td>{{PROJECT_NAME}}</td></tr>\n    <tr><td><strong>Main contact</strong></td><td>{{CONTACT_NAME}} — {{CONTACT_EMAIL}}</td></tr>\n    <tr><td><strong>Kickoff</strong></td><td>{{KICKOFF_DATE}}</td></tr>\n    <tr><td><strong>Tools we'll use</strong></td><td>{{TOOLS}}</td></tr>\n  </tbody>\n</table>\n<h2>What we need from you</h2>\n{{CHECKLIST}}\n<h2>How we communicate</h2>\n<p>{{COMMS_POLICY}}</p>\n<div class=\"small muted\" style=\"margin-top:30px\">Questions? {{AGENCY_EMAIL}}</div>\n</body>\n</html>\n";

// ---- Agency constants (edit to your real branding) ----
const AGENCY_NAME = 'Your Agency';
const AGENCY_EMAIL = 'achrafrachek1@gmail.com';
const CONTACT_NAME = 'Achraf Rachek';
const CONTACT_EMAIL = 'achrafrachek1@gmail.com';
const LOGO_B64 = '';

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;');

// Pull the raw model text, then try to parse the JSON it returned.
const raw = String($json.response || '');
let data = {};
try {
  const m = raw.match(/\{[\s\S]*\}/);
  data = JSON.parse(m ? m[0] : raw);
} catch (e) {
  data = {};
}

const clientName = $('Build Prompt').first().json.clientName || 'Valued Client';
const projectName = $('Build Prompt').first().json.projectName || 'Your Project';
const startDate = $('Build Prompt').first().json.startDate || '[PLACEHOLDER: kickoff date]';
const firstName = clientName.split(' ')[0] || clientName;

const welcome = data.welcome ? `<p>${esc(data.welcome)}</p>` : '';
const commsPolicy = esc(data.comms_policy || '[PLACEHOLDER: communication policy]');
const tools = esc(data.tools || 'email, shared drive, project board');

const toList = (arr, ordered) => {
  const items = Array.isArray(arr) ? arr : [];
  if (!items.length) return '<p class=\"muted\">[PLACEHOLDER: details to follow]</p>';
  const lis = items.map((x) => `<li>${esc(x)}</li>`).join('');
  return ordered ? `<ol>${lis}</ol>` : `<ul>${lis}</ul>`;
};

const stepsList = welcome + toList(data.steps, true);
const checklist = toList(data.checklist, false);

const html = TEMPLATE
  .replace(/\{\{LOGO_B64\}\}/g, LOGO_B64)
  .replace(/\{\{AGENCY_NAME\}\}/g, esc(AGENCY_NAME))
  .replace(/\{\{CLIENT_FIRST_NAME\}\}/g, esc(firstName))
  .replace(/\{\{STEPS_LIST\}\}/g, stepsList)
  .replace(/\{\{PROJECT_NAME\}\}/g, esc(projectName))
  .replace(/\{\{CONTACT_NAME\}\}/g, esc(CONTACT_NAME))
  .replace(/\{\{CONTACT_EMAIL\}\}/g, esc(CONTACT_EMAIL))
  .replace(/\{\{KICKOFF_DATE\}\}/g, esc(startDate))
  .replace(/\{\{TOOLS\}\}/g, tools)
  .replace(/\{\{CHECKLIST\}\}/g, checklist)
  .replace(/\{\{COMMS_POLICY\}\}/g, commsPolicy)
  .replace(/\{\{AGENCY_EMAIL\}\}/g, esc(AGENCY_EMAIL));

const safeClient = clientName.replace(/[^a-z0-9]+/gi, '-').replace(/^-+|-+$/g, '') || 'client';
return [{ json: { html, fileName: `onboarding-${safeClient}.pdf` } }];
